-- Rogue Poisons: brings back the Poisons skill (removed in WotLK) and its recipes.
-- Pairs with IP's optional/sql/world/zz_optional_restore_rogue_poisons.sql, which takes poisons off the vendors.

-- SkillLine 40: Poisons
DELETE FROM `skillline` WHERE `id` = @PoisonsSkill;

-- Who may learn it: every playable race (IP: all bits set), Rogues only
DELETE FROM `skillraceclassinfo` WHERE `id` = 80;

-- Recipes (skill_grey_level/skill_yellow_level: the skill at which they turn grey/yellow)
DELETE FROM `skilllineability` WHERE `id` IN (1687, 1688, 1689, 1959, 3626, 3969, 4806, 4807, 4808, 4809, 4810, 5966, 5967, 5968, 5969, 5970, 5986, 5987, 7256, 7257, 7258, 7259, 13240, 13473, 13718, 13719, 13720, 13722);

-- ---------------------------------------------------------------------------------------------------------------------
-- Spell.dbc
-- The poison recipes and the poisons' effects (stock 3.3.5 sells them and has no recipe spells)

-- New spells
DELETE FROM `spell` WHERE `id` IN (2835, 2837, 3420, 3421, 5763, 6510, 8681, 8687, 8691, 8692, 8693, 8694, 11201, 11202, 11341, 11342, 11343, 11357, 11358, 11398, 11399, 11400, 13220, 13228, 13229, 13230, 25347, 26786, 26892, 26969, 27282, 27283);

-- Changed spells
UPDATE `spell` SET `proc_chance` = 30, `spell_tooltip_flags` = 16712190 WHERE `id` = 3408; -- Crippling Poison (Rank 1)
UPDATE `spell` SET `equipped_item_subclass_mask` = `equipped_item_subclass_mask` | 1, `effect_base_points_1` = -51, `spell_subtext_enus` = 'Rank 1' WHERE `id` = 3409; -- Crippling Poison
UPDATE `spell` SET `equipped_item_subclass_mask` = `equipped_item_subclass_mask` | 1, `effect_base_points_1` = -41, `spell_subtext_enus` = 'Rank 1' WHERE `id` = 5760; -- Mind-numbing Poison
UPDATE `spell` SET `proc_chance` = 20, `spell_subtext_enus` = 'Rank 1', `spell_tooltip_flags` = 16712190 WHERE `id` = 5761; -- Mind-numbing Poison
UPDATE `spell` SET `spell_focus_object` = 1589 WHERE `id` = 57144; -- Glyph of Crippling Poison

-- Poisons (2995), the spell the rogue poison quests reward, learns the Poisons skill (2842); IP adds Instant Poison (8681)
-- (IP: spell_dbc row in zz_optional_restore_rogue_poisons.sql)
UPDATE `spell` SET `effect_3` = 36, `effect_trigger_spell_3` = 8681 WHERE `id` = 2995;
